import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";

const eslintConfig = defineConfig([
  ...nextVitals,
  ...nextTs,
  globalIgnores([
    ".next/**",
    "out/**",
    "build/**",
    "next-env.d.ts",
    "node_modules/**",
  ]),
]);

export default eslintConfig;

const config = {
  printWidth: 100,
  singleQuote: false,
  trailingComma: "all",
  semi: true,
  tabWidth: 2,
};

export default config;

import { defineConfig } from "@playwright/test";

export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: "html",
  use: {
    baseURL: "http://localhost:3000",
    trace: "on-first-retry",
  },
  webServer: {
    command: "npm run dev",
    url: "http://localhost:3000",
    reuseExistingServer: !process.env.CI,
  },
  projects: [
    {
      name: "chromium",
      use: {
        browserName: "chromium",
        viewport: { width: 1440, height: 900 },
      },
    },
    {
      name: "tablet",
      use: {
        browserName: "chromium",
        viewport: { width: 768, height: 1024 },
      },
    },
    {
      name: "mobile",
      use: {
        browserName: "chromium",
        viewport: { width: 375, height: 812 },
      },
    },
  ],
});

export interface Profile {
  name: string;
  title: string;
  tagline: string;
  summary: string;
  email: string;
  linkedin: string;
  github: string;
  resumeUrl: string;
  location: string;
}

export interface Metric {
  label: string;
  value: string;
  suffix?: string;
  placeholder?: boolean;
}

export interface SkillCategory {
  title: string;
  icon: string;
  skills: Skill[];
}

export interface Skill {
  name: string;
  level: "beginner" | "intermediate" | "advanced" | "expert";
}

export interface Experience {
  company: string;
  role: string;
  duration: string;
  location: string;
  summary: string;
  responsibilities: string[];
  technologies: string[];
  achievements: string[];
}

export interface Project {
  slug: string;
  name: string;
  type: string;
  role: string;
  technologies: string[];
  testingAreas: string[];
  shortDescription: string;
  keyContributions: string[];
  featured: boolean;
}

export interface CaseStudy {
  slug: string;
  title: string;
  project: string;
  overview: string;
  businessContext: string;
  testingScope: string;
  problem: string;
  investigation: string;
  testingApproach: string;
  rootCause: string;
  bug: BugDetail;
  resolution: string;
  validation: string;
  outcome: string;
}

export interface BugDetail {
  severity: string;
  priority: string;
  environment: string;
  module: string;
  issue: string;
  impact: string;
  expectedResult: string;
  actualResult: string;
  rootCause: string;
  status: string;
}

export interface NavLink {
  label: string;
  href: string;
}

export interface SocialLink {
  label: string;
  href: string;
  icon: string;
}

export interface TestingStage {
  stage: string;
  description: string;
  icon: string;
}

