@import "tailwindcss";

@theme {
  --color-void: #05070A;
  --color-deep: #0B1017;
  --color-surface: #111923;
  --color-text: #F5F7FA;
  --color-text-dim: #8B95A5;
  --color-accent: #38BDF8;
  --color-accent-glow: rgba(56, 189, 248, 0.15);
  --color-accent-subtle: rgba(56, 189, 248, 0.06);
  --color-border: rgba(255, 255, 255, 0.06);
  --color-border-strong: rgba(255, 255, 255, 0.12);
  --color-error: #f87171;
  --color-success: #34d399;
  --font-geist: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  background: #05070A;
  color: #F5F7FA;
  font-family: var(--font-geist), system-ui, sans-serif;
  overflow-x: hidden;
}

html, body {
  height: 100%;
  cursor: none !important;
}

body {
  background: #05070A;
  overflow-x: hidden;
}

/* Hide default scrollbar */
::-webkit-scrollbar { width: 0; height: 0; }
* { scrollbar-width: none; }

/* Selection */
::selection {
  background: rgba(56, 189, 248, 0.3);
  color: #F5F7FA;
}

/* Canvas container */
.canvas-container {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.canvas-container canvas {
  pointer-events: auto;
}

/* Content layer */
.content-layer {
  position: relative;
  z-index: 1;
  pointer-events: none;
}

.content-layer * {
  pointer-events: auto;
}

/* Section base */
.ry-section {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

/* Glass morphism */
.glass {
  background: rgba(10, 10, 18, 0.6);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

/* Gradient text */
.gradient-text {
  background: linear-gradient(135deg, #38BDF8, #818CF8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Glow effects */
.glow-accent {
  box-shadow: 0 0 40px rgba(56, 189, 248, 0.1), 0 0 80px rgba(56, 189, 248, 0.05);
}

.text-glow {
  text-shadow: 0 0 30px rgba(56, 189, 248, 0.3);
}

/* Magnetic button base */
.magnetic-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 9999px;
  background: rgba(56, 189, 248, 0.05);
  color: #38BDF8;
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: none !important;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}

.magnetic-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), rgba(56, 189, 248, 0.15), transparent 60%);
  opacity: 0;
  transition: opacity 0.4s;
}

.magnetic-btn:hover::before {
  opacity: 1;
}

.magnetic-btn:hover {
  border-color: rgba(56, 189, 248, 0.6);
  box-shadow: 0 0 30px rgba(56, 189, 248, 0.15);
}

/* System label */
.system-label {
  font-family: var(--font-mono), monospace;
  font-size: 0.625rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #8B95A5;
}

/* Scan line */
@keyframes scan {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}

.scan-line {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(56, 189, 248, 0.1), transparent);
  pointer-events: none;
  z-index: 100;
  animation: scan 8s linear infinite;
  opacity: 0.3;
}

/* Boot sequence */
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.cursor-blink {
  animation: blink 1s step-end infinite;
}

/* Fade in up */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-in-up {
  animation: fadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Particle fade */
@keyframes particleFade {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}

/* Responsive */
@media (max-width: 768px) {
  html, body {
    cursor: auto !important;
  }

  .magnetic-btn {
    cursor: pointer !important;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  .scan-line { display: none; }
}

"use client";

import { useRef, useCallback, useEffect, useState } from "react";

interface MouseState {
  x: number;
  y: number;
  vx: number;
  vy: number;
  speed: number;
  normalX: number;
  normalY: number;
}

export function useMouse() {
  const state = useRef<MouseState>({
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
    speed: 0,
    normalX: 0,
    normalY: 0,
  });

  const spring = useRef({ x: 0, y: 0 });
  const raf = useRef<number>(0);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [smoothPosition, setSmoothPosition] = useState({ x: 0, y: 0 });
  const [velocity, setVelocity] = useState(0);
  const [isMoving, setIsMoving] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout>();

  const handleMouseMove = useCallback((e: MouseEvent) => {
    const prev = { x: state.current.x, y: state.current.y };
    state.current.x = e.clientX;
    state.current.y = e.clientY;
    state.current.vx = e.clientX - prev.x;
    state.current.vy = e.clientY - prev.y;
    state.current.speed = Math.sqrt(state.current.vx ** 2 + state.current.vy ** 2);
    state.current.normalX = (e.clientX / window.innerWidth) * 2 - 1;
    state.current.normalY = -(e.clientY / window.innerHeight) * 2 + 1;
    setIsMoving(true);

    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setIsMoving(false), 150);
  }, []);

  useEffect(() => {
    window.addEventListener("mousemove", handleMouseMove, { passive: true });

    const animate = () => {
      const s = state.current;
      const springFactor = 0.08;
      const damping = 0.92;

      spring.current.x += (s.x - spring.current.x) * springFactor;
      spring.current.y += (s.y - spring.current.y) * springFactor;

      setPosition({ x: s.x, y: s.y });
      setSmoothPosition({ x: spring.current.x, y: spring.current.y });
      setVelocity(s.speed);

      raf.current = requestAnimationFrame(animate);
    };
    raf.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      cancelAnimationFrame(raf.current);
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [handleMouseMove]);

  return {
    position,
    smoothPosition,
    velocity,
    isMoving,
    state,
  };
}

"use client";

import { createContext, useContext, useState, useCallback, ReactNode } from "react";

export type CursorContext = {
  variant: "default" | "hover" | "expand" | "drag" | "text";
  label: string;
  setCursor: (variant: CursorContext["variant"], label?: string) => void;
};

const CursorContextProvider = createContext<CursorContext>({
  variant: "default",
  label: "",
  setCursor: () => {},
});

export function CursorProvider({ children }: { children: ReactNode }) {
  const [cursor, setCursorState] = useState<{
    variant: CursorContext["variant"];
    label: string;
  }>({ variant: "default", label: "" });

  const setCursor = useCallback(
    (variant: CursorContext["variant"], label = "") => {
      setCursorState({ variant, label });
    },
    [],
  );

  return (
    <CursorContextProvider.Provider value={{ ...cursor, setCursor }}>
      {children}
    </CursorContextProvider.Provider>
  );
}

export function useCursor() {
  return useContext(CursorContextProvider);
}

"use client";

import { useEffect, useRef } from "react";
import { useMouse } from "@/hooks/useMouse";
import { useCursor } from "@/hooks/useCursorContext";

export default function CustomCursor() {
  const { smoothPosition, velocity, isMoving } = useMouse();
  const { variant, label } = useCursor();
  const dotRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);
  const labelRef = useRef<HTMLDivElement>(null);

  const sizeMap = {
    default: { dot: 6, ring: 32 },
    hover: { dot: 8, ring: 48 },
    expand: { dot: 10, ring: 64 },
    drag: { dot: 8, ring: 56 },
    text: { dot: 4, ring: 24 },
  };

  const size = sizeMap[variant] || sizeMap.default;

  useEffect(() => {
    if (!dotRef.current || !ringRef.current) return;

    const dot = dotRef.current;
    const ring = ringRef.current;
    const lbl = labelRef.current;

    dot.style.transform = `translate(${smoothPosition.x - size.dot / 2}px, ${smoothPosition.y - size.dot / 2}px)`;
    ring.style.transform = `translate(${smoothPosition.x - size.ring / 2}px, ${smoothPosition.y - size.ring / 2}px) scale(${isMoving ? 1 + Math.min(velocity * 0.005, 0.3) : 1})`;

    if (lbl) {
      lbl.style.transform = `translate(${smoothPosition.x}px, ${smoothPosition.y + 24}px)`;
    }
  }, [smoothPosition, velocity, isMoving, size]);

  return (
    <>
      {/* Dot */}
      <div
        ref={dotRef}
        className="fixed top-0 left-0 pointer-events-none z-[9999] mix-blend-difference"
        style={{
          width: size.dot,
          height: size.dot,
          borderRadius: "50%",
          background: variant === "default" ? "#38BDF8" : "#fff",
          transition: "width 0.3s, height 0.3s, background 0.3s",
          willChange: "transform",
        }}
      />

      {/* Ring */}
      <div
        ref={ringRef}
        className="fixed top-0 left-0 pointer-events-none z-[9998]"
        style={{
          width: size.ring,
          height: size.ring,
          borderRadius: "50%",
          border: `1px solid ${variant === "default" ? "rgba(56, 189, 248, 0.3)" : "rgba(255, 255, 255, 0.4)"}`,
          transition: "width 0.4s cubic-bezier(0.16, 1, 0.3, 1), height 0.4s cubic-bezier(0.16, 1, 0.3, 1), border 0.3s",
          willChange: "transform",
        }}
      />

      {/* Label */}
      {label && (
        <div
          ref={labelRef}
          className="fixed top-0 left-0 pointer-events-none z-[9999] mix-blend-difference"
          style={{
            transform: `translate(${smoothPosition.x}px, ${smoothPosition.y + 24}px)`,
            transition: "opacity 0.2s",
            willChange: "transform",
          }}
        >
          <span
            className="font-mono text-[10px] tracking-[0.2em] uppercase whitespace-nowrap"
            style={{
              color: "#F5F7FA",
              textShadow: "0 0 10px rgba(56, 189, 248, 0.5)",
            }}
          >
            {label}
          </span>
        </div>
      )}
    </>
  );
}

