"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import SectionLabel from "@/components/ui/SectionLabel";
import MagneticButton from "@/components/ui/MagneticButton";
import { useCursor } from "@/hooks/useCursorContext";
import { profile } from "@/data/profile";

type SubmissionState = "idle" | "validating" | "sending" | "success" | "error";

export default function ContactSection() {
  const [form, setForm] = useState({ name: "", email: "", subject: "", message: "" });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [state, setState] = useState<SubmissionState>("idle");
  const { setCursor } = useCursor();

  const validate = () => {
    const errs: Record<string, string> = {};
    if (!form.name.trim()) errs.name = "Name is required";
    if (!form.email.trim()) errs.email = "Email is required";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) errs.email = "Invalid email";
    if (!form.subject.trim()) errs.subject = "Subject is required";
    if (!form.message.trim()) errs.message = "Message is required";
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setState("validating");
    await new Promise((r) => setTimeout(r, 600));

    setState("sending");
    try {
      const res = await fetch("/api/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (res.ok) {
        setState("success");
        setForm({ name: "", email: "", subject: "", message: "" });
        setTimeout(() => setState("idle"), 4000);
      } else {
        setState("error");
        setTimeout(() => setState("idle"), 3000);
      }
    } catch {
      setState("error");
      setTimeout(() => setState("idle"), 3000);
    }
  };

  const handleChange = (field: string, value: string) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors((prev) => ({ ...prev, [field]: "" }));
  };

  return (
    <section
      id="contact"
      className="relative min-h-screen flex items-center justify-center px-6 py-24"
    >
      <div className="absolute inset-0 pointer-events-none">
        <div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[700px] rounded-full"
          style={{
            background:
              "radial-gradient(circle, rgba(56, 189, 248, 0.04) 0%, transparent 70%)",
          }}
        />
      </div>

      <div className="relative z-10 max-w-4xl mx-auto w-full">
        <SectionLabel number="07" />

        <motion.h2
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          className="text-4xl sm:text-5xl font-bold tracking-tight mb-6 text-[#F5F7FA] text-center"
        >
          Establish <span className="gradient-text">Connection</span>
        </motion.h2>

        <motion.p
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          className="text-[#8B95A5] mb-12 text-center max-w-md mx-auto"
        >
          Ready to collaborate? Send a transmission or connect through the channels
          below.
        </motion.p>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          {/* Form */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
          >
            <AnimatePresence mode="wait">
              {state === "success" ? (
                <motion.div
                  key="success"
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0 }}
                  className="p-8 rounded-2xl border border-[rgba(52,211,153,0.2)] bg-[rgba(52,211,153,0.05)] text-center"
                >
                  <div className="text-4xl mb-4">✓</div>
                  <h3 className="text-lg font-bold text-[#34D399] mb-2">
                    MESSAGE DELIVERED
                  </h3>
                  <p className="text-sm text-[#8B95A5]">
                    Transmission successful. I will respond shortly.
                  </p>
                </motion.div>
              ) : state === "error" ? (
                <motion.div
                  key="error"
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0 }}
                  className="p-8 rounded-2xl border border-[rgba(248,113,113,0.2)] bg-[rgba(248,113,113,0.05)] text-center"
                >
                  <div className="text-4xl mb-4">✕</div>
                  <h3 className="text-lg font-bold text-[#f87171] mb-2">
                    TRANSMISSION FAILED
                  </h3>
                  <p className="text-sm text-[#8B95A5]">
                    Connection error. Please try again or reach out directly.
                  </p>
                </motion.div>
              ) : (
                <motion.form
                  key="form"
                  onSubmit={handleSubmit}
                  className="space-y-4"
                >
                  {/* Name */}
                  <div>
                    <label className="block font-mono text-[10px] tracking-[0.15em] text-[#8B95A5] mb-1.5">
                      NAME
                    </label>
                    <input
                      type="text"
                      value={form.name}
                      onChange={(e) => handleChange("name", e.target.value)}
                      className="w-full px-4 py-3 rounded-xl border border-[rgba(56,189,248,0.1)] bg-[rgba(5,7,10,0.6)] text-[#F5F7FA] text-sm focus:outline-none focus:border-[rgba(56,189,248,0.4)] transition-colors cursor-none"
                      placeholder="Your name"
                    />
                    {errors.name && (
                      <span className="text-[10px] text-[#f87171]">{errors.name}</span>
                    )}
                  </div>

                  {/* Email */}
                  <div>
                    <label className="block font-mono text-[10px] tracking-[0.15em] text-[#8B95A5] mb-1.5">
                      EMAIL
                    </label>
                    <input
                      type="text"
                      value={form.email}
                      onChange={(e) => handleChange("email", e.target.value)}
                      className="w-full px-4 py-3 rounded-xl border border-[rgba(56,189,248,0.1)] bg-[rgba(5,7,10,0.6)] text-[#F5F7FA] text-sm focus:outline-none focus:border-[rgba(56,189,248,0.4)] transition-colors cursor-none"
                      placeholder="your@email.com"
                    />
                    {errors.email && (
                      <span className="text-[10px] text-[#f87171]">{errors.email}</span>
                    )}
                  </div>

                  {/* Subject */}
                  <div>
                    <label className="block font-mono text-[10px] tracking-[0.15em] text-[#8B95A5] mb-1.5">
                      SUBJECT
                    </label>
                    <input
                      type="text"
                      value={form.subject}
                      onChange={(e) => handleChange("subject", e.target.value)}
                      className="w-full px-4 py-3 rounded-xl border border-[rgba(56,189,248,0.1)] bg-[rgba(5,7,10,0.6)] text-[#F5F7FA] text-sm focus:outline-none focus:border-[rgba(56,189,248,0.4)] transition-colors cursor-none"
                      placeholder="What's this about?"
                    />
                    {errors.subject && (
                      <span className="text-[10px] text-[#f87171]">{errors.subject}</span>
                    )}
                  </div>

                  {/* Message */}
                  <div>
                    <label className="block font-mono text-[10px] tracking-[0.15em] text-[#8B95A5] mb-1.5">
                      MESSAGE
                    </label>
                    <textarea
                      value={form.message}
                      onChange={(e) => handleChange("message", e.target.value)}
                      rows={4}
                      className="w-full px-4 py-3 rounded-xl border border-[rgba(56,189,248,0.1)] bg-[rgba(5,7,10,0.6)] text-[#F5F7FA] text-sm focus:outline-none focus:border-[rgba(56,189,248,0.4)] transition-colors resize-none cursor-none"
                      placeholder="Your message..."
                    />
                    {errors.message && (
                      <span className="text-[10px] text-[#f87171]">{errors.message}</span>
                    )}
                  </div>

                  {/* Submit */}
                  <MagneticButton
                    cursorLabel={
                      state === "validating"
                        ? "VALIDATING"
                        : state === "sending"
                          ? "TRANSMITTING"
                          : "TRANSMIT"
                    }
                  >
                    {state === "validating"
                      ? "VALIDATING..."
                      : state === "sending"
                        ? "TRANSMITTING..."
                        : "TRANSMIT MESSAGE"}
                  </MagneticButton>
                </motion.form>
              )}
            </AnimatePresence>
          </motion.div>

          {/* Channels */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            className="space-y-6"
          >
            <div className="p-6 rounded-2xl border border-[rgba(56,189,248,0.08)] bg-[rgba(5,7,10,0.5)]">
              <h3 className="font-mono text-[10px] tracking-[0.2em] text-[#8B95A5] mb-4">
                DIRECT CHANNELS
              </h3>

              {[
                {
                  label: "EMAIL",
                  value: profile.email,
                  href: `mailto:${profile.email}`,
                  icon: "✉",
                },
                {
                  label: "LINKEDIN",
                  value: "rohit-yadav",
                  href: profile.linkedin,
                  icon: "◆",
                },
                {
                  label: "GITHUB",
                  value: "rohity0611",
                  href: profile.github,
                  icon: "◇",
                },
              ].map((channel) => (
                <a
                  key={channel.label}
                  href={channel.href}
                  target={channel.href.startsWith("mailto") ? undefined : "_blank"}
                  rel="noopener noreferrer"
                  className="flex items-center gap-4 p-3 rounded-xl border border-transparent hover:border-[rgba(56,189,248,0.15)] hover:bg-[rgba(56,189,248,0.03)] transition-all duration-300 cursor-none group"
                  onMouseEnter={() => setCursor("hover", "OPEN")}
                  onMouseLeave={() => setCursor("default")}
                >
                  <span className="text-lg">{channel.icon}</span>
                  <div>
                    <span className="font-mono text-[10px] tracking-[0.15em] text-[#8B95A5] block">
                      {channel.label}
                    </span>
                    <span className="text-sm text-[#F5F7FA] group-hover:text-[#38BDF8] transition-colors">
                      {channel.value}
                    </span>
                  </div>
                </a>
              ))}
            </div>

            <div className="p-6 rounded-2xl border border-[rgba(56,189,248,0.08)] bg-[rgba(5,7,10,0.5)]">
              <h3 className="font-mono text-[10px] tracking-[0.2em] text-[#8B95A5] mb-3">
                LOCATION
              </h3>
              <p className="text-sm text-[#F5F7FA]">{profile.location}</p>
              <p className="text-xs text-[#8B95A5] mt-1">{profile.phone}</p>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { Resend } from "resend";

const resend = new Resend(process.env.RESEND_API_KEY);

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { name, email, subject, message } = body;

    if (!name || !email || !subject || !message) {
      return NextResponse.json(
        { success: false, message: "All fields are required" },
        { status: 400 },
      );
    }

    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return NextResponse.json(
        { success: false, message: "Invalid email address" },
        { status: 400 },
      );
    }

    const { error } = await resend.emails.send({
      from: "RY/OS Portfolio <onboarding@resend.dev>",
      to: "yadavrohit0660@gmail.com",
      replyTo: email,
      subject: `[RY/OS] ${subject}`,
      html: `
        <div style="font-family: system-ui, sans-serif; max-width: 600px; margin: 0 auto; padding: 32px; background: #0B1017; color: #F5F7FA;">
          <div style="border-bottom: 1px solid rgba(56, 189, 248, 0.2); padding-bottom: 16px; margin-bottom: 24px;">
            <h1 style="font-size: 14px; color: #38BDF8; letter-spacing: 0.1em; margin: 0;">RY/OS INCOMING TRANSMISSION</h1>
          </div>
          <p style="color: #8B95A5; font-size: 12px; letter-spacing: 0.1em; margin-bottom: 4px;">FROM</p>
          <p style="margin: 0 0 16px; font-size: 16px;">${name} &lt;${email}&gt;</p>
          <p style="color: #8B95A5; font-size: 12px; letter-spacing: 0.1em; margin-bottom: 4px;">SUBJECT</p>
          <p style="margin: 0 0 16px; font-size: 16px;">${subject}</p>
          <p style="color: #8B95A5; font-size: 12px; letter-spacing: 0.1em; margin-bottom: 4px;">MESSAGE</p>
          <div style="padding: 16px; background: rgba(56, 189, 248, 0.05); border: 1px solid rgba(56, 189, 248, 0.1); border-radius: 8px; font-size: 14px; line-height: 1.6; white-space: pre-wrap;">${message}</div>
          <div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid rgba(56, 189, 248, 0.1); text-align: center;">
            <p style="color: #8B95A5; font-size: 10px; letter-spacing: 0.15em; margin: 0;">SENT VIA RY/OS PORTFOLIO</p>
          </div>
        </div>
      `,
    });

    if (error) {
      return NextResponse.json(
        { success: false, message: "Failed to send message" },
        { status: 500 },
      );
    }

    return NextResponse.json({
      success: true,
      message: "Message delivered successfully",
    });
  } catch {
    return NextResponse.json(
      { success: false, message: "Internal server error" },
      { status: 500 },
    );
  }
}

