              <span className="font-mono text-xs sm:text-sm tracking-[0.15em] text-[#8B95A5] uppercase">
                QA Engineer
              </span>
            </motion.div>

            {/* Tagline */}
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.8, delay: 0.7 }}
              className="text-lg sm:text-xl text-[#8B95A5] mb-12 max-w-lg mx-auto lg:mx-0 font-light"
