              <div className="w-full h-full rounded-2xl bg-[#0B1017] flex items-center justify-center overflow-hidden">
                <span className="text-4xl font-bold gradient-text">RY</span>
              </div>
              {/* Holographic scan line */}
              <motion.div
                animate={{ y: ["-100%", "200%"] }}
                transition={{ duration: 3, repeat: Infinity, ease: "linear" }}
                className="absolute inset-0 pointer-events-none"
                style={{
                  background:
                    "linear-gradient(transparent 0%, rgba(56, 189, 248, 0.05) 50%, transparent 100%)",
                  height: "30%",
                }}
              />
            </div>
          </motion.div>
        </div>
      </div>

      {/* Scroll indicator */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 2, duration: 1 }}
        className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2"
      >
        <span className="font-mono text-[9px] tracking-[0.2em] text-[#8B95A5]">SCROLL</span>
        <motion.div
          animate={{ y: [0, 6, 0] }}
          transition={{ duration: 1.5, repeat: Infinity }}
          className="w-[1px] h-8 bg-gradient-to-b from-[#38BDF8] to-transparent"
        />
      </motion.div>
    </section>
  );
}

