.content-layer {
  position: relative;
  z-index: 1;
  pointer-events: none;
}

.content-layer * {
  pointer-events: auto;
}

/* Section base */
.ry-section {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

