import { test, expect } from "@playwright/test";

test.describe("Page load", () => {
  test("homepage loads with correct title", async ({ page }) => {
    await page.goto("/");
    await expect(page).toHaveTitle(/Rohit Yadav/);
  });

  test("hero section is visible with name and title", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await expect(page.getByText("ROHIT")).toBeVisible();
    await expect(page.getByText("YADAV")).toBeVisible();
    await expect(page.getByText("QA Engineer")).toBeVisible();
  });

  test("main landmark is present", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByRole("main")).toBeVisible();
  });
});

test.describe("Scroll", () => {
  test("page can scroll down", async ({ page }) => {
    await page.goto("/");
    const scrollYBefore = await page.evaluate(() => window.scrollY);
    await page.evaluate(() => window.scrollBy(0, 500));
    const scrollYAfter = await page.evaluate(() => window.scrollY);
    expect(scrollYAfter).toBeGreaterThan(scrollYBefore);
  });

  test("no horizontal overflow on desktop", async ({ page }) => {
    await page.goto("/");
    const bodyWidth = await page.evaluate(() => document.body.scrollWidth);
    const viewportWidth = await page.evaluate(() => window.innerWidth);
    expect(bodyWidth).toBeLessThanOrEqual(viewportWidth + 5);
  });
});

test.describe("Desktop navigation", () => {
  test.use({ viewport: { width: 1440, height: 900 } });

  test("desktop nav is visible", async ({ page }) => {
    await page.goto("/");
    const nav = page.getByRole("navigation");
    await expect(nav).toBeVisible();
  });

  test("desktop nav has all section links", async ({ page }) => {
    await page.goto("/");
    const nav = page.getByRole("navigation");
    await expect(nav.getByText("ABOUT")).toBeVisible();
    await expect(nav.getByText("EXPERIENCE")).toBeVisible();
    await expect(nav.getByText("SKILLS")).toBeVisible();
    await expect(nav.getByText("QA LAB")).toBeVisible();
    await expect(nav.getByText("PROJECTS")).toBeVisible();
    await expect(nav.getByText("CONTACT")).toBeVisible();
  });

  test("desktop resume link is present", async ({ page }) => {
    await page.goto("/");
    const resumeLink = page.getByRole("link", { name: "RESUME" }).first();
    await expect(resumeLink).toBeVisible();
  });

  test("desktop nav scrolls to section", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("navigation").getByText("ABOUT").click();
    await page.waitForTimeout(1000);
    const aboutSection = page.locator("#about");
    await expect(aboutSection).toBeVisible();
  });
});

test.describe("Mobile sidebar", () => {
  test.use({ viewport: { width: 375, height: 812 } });

  test("mobile menu button is visible", async ({ page }) => {
    await page.goto("/");
    const menuButton = page.getByRole("button", { name: /open navigation menu/i });
    await expect(menuButton).toBeVisible();
  });

  test("mobile sidebar opens on menu click", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar).toBeVisible();
  });

  test("mobile sidebar has nav links", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar.getByText("ABOUT")).toBeVisible();
    await expect(sidebar.getByText("EXPERIENCE")).toBeVisible();
    await expect(sidebar.getByText("PROJECTS")).toBeVisible();
    await expect(sidebar.getByText("CONTACT")).toBeVisible();
  });

  test("mobile sidebar has resume link", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar.getByText("RESUME")).toBeVisible();
  });

  test("mobile sidebar closes on close button", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    await page.getByRole("button", { name: /close navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar).not.toBeVisible();
  });

  test("mobile sidebar closes on Escape key", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar).toBeVisible();
    await page.keyboard.press("Escape");
    await expect(sidebar).not.toBeVisible();
  });

  test("mobile sidebar closes on backdrop click", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    // Click the backdrop (the semi-transparent overlay behind sidebar)
    const backdrop = page.locator(".fixed.inset-0.z-\\[101\\]");
    await backdrop.click({ position: { x: 50, y: 400 } });
    const sidebar = page.locator("#mobile-sidebar");
    await expect(sidebar).not.toBeVisible();
  });

  test("mobile sidebar nav link scrolls to section and closes", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: /open navigation menu/i }).click();
    const sidebar = page.locator("#mobile-sidebar");
    await sidebar.getByText("ABOUT").click();
    await page.waitForTimeout(1000);
    await expect(sidebar).not.toBeVisible();
  });

  test("no horizontal overflow on mobile", async ({ page }) => {
    await page.goto("/");
    const bodyWidth = await page.evaluate(() => document.body.scrollWidth);
    const viewportWidth = await page.evaluate(() => window.innerWidth);
    expect(bodyWidth).toBeLessThanOrEqual(viewportWidth + 10);
  });
});

test.describe("Tablet", () => {
  test.use({ viewport: { width: 768, height: 1024 } });

  test("no horizontal overflow on tablet", async ({ page }) => {
    await page.goto("/");
    const bodyWidth = await page.evaluate(() => document.body.scrollWidth);
    const viewportWidth = await page.evaluate(() => window.innerWidth);
    expect(bodyWidth).toBeLessThanOrEqual(viewportWidth + 10);
  });
});

import { test, expect } from "@playwright/test";

test.describe("Resume", () => {
  test("resume link exists in desktop nav", async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto("/");
    const resumeLink = page.getByRole("link", { name: "RESUME" }).first();
    await expect(resumeLink).toBeVisible();
    await expect(resumeLink).toHaveAttribute("href", "/certificates/Rohit-Yadav-CV.pdf");
  });

  test("resume PDF is accessible", async ({ page }) => {
    const response = await page.goto("/certificates/Rohit-Yadav-CV.pdf");
    expect(response?.status()).toBe(200);
  });
});

test.describe("Contact form", () => {
  test("contact form is visible", async ({ page }) => {
    await page.goto("/");
    const contactSection = page.locator("#contact");
    await contactSection.scrollIntoViewIfNeeded();
    await expect(page.getByLabel("NAME")).toBeVisible();
    await expect(page.getByLabel("EMAIL")).toBeVisible();
    await expect(page.getByLabel("SUBJECT")).toBeVisible();
    await expect(page.getByLabel("MESSAGE")).toBeVisible();
  });

  test("contact form validates empty submission", async ({ page }) => {
    await page.goto("/");
    const contactSection = page.locator("#contact");
    await contactSection.scrollIntoViewIfNeeded();
    await page.getByRole("button", { name: /TRANSMIT MESSAGE/i }).click();
    await expect(page.getByText("Name is required")).toBeVisible();
    await expect(page.getByText("Email is required")).toBeVisible();
  });

  test("contact form validates invalid email", async ({ page }) => {
    await page.goto("/");
    const contactSection = page.locator("#contact");
    await contactSection.scrollIntoViewIfNeeded();
    await page.getByLabel("NAME").fill("Test User");
    // foo@bar is accepted by browser's type=email but fails regex (no dot)
    await page.getByLabel("EMAIL").fill("foo@bar");
    await page.getByLabel("SUBJECT").fill("Test");
    await page.getByLabel("MESSAGE").fill("Test message content here.");
    await page.getByRole("button", { name: /TRANSMIT MESSAGE/i }).click();
    await expect(page.getByText("Invalid email")).toBeVisible();
  });

  test("contact form accepts valid email", async ({ page }) => {
    await page.goto("/");
    const contactSection = page.locator("#contact");
    await contactSection.scrollIntoViewIfNeeded();
    await page.getByLabel("NAME").fill("Test User");
    await page.getByLabel("EMAIL").fill("test@example.com");
    await page.getByLabel("SUBJECT").fill("Test Subject");
    await page.getByLabel("MESSAGE").fill("Test message content here.");
    await page.getByRole("button", { name: /TRANSMIT MESSAGE/i }).click();
    // Should not show validation errors
    await expect(page.getByText("Name is required")).not.toBeVisible();
    await expect(page.getByText("Email is required")).not.toBeVisible();
  });
});

test.describe("Sections", () => {
  test("all major sections exist", async ({ page }) => {
    await page.goto("/");
    await expect(page.locator("#hero")).toBeAttached();
    await expect(page.locator("#about")).toBeAttached();
    await expect(page.locator("#experience")).toBeAttached();
    await expect(page.locator("#skills")).toBeAttached();
    await expect(page.locator("#qa-lab")).toBeAttached();
    await expect(page.locator("#projects")).toBeAttached();
    await expect(page.locator("#contact")).toBeAttached();
  });

  test("QA Lab section displays stages", async ({ page }) => {
    await page.goto("/");
    const qaSection = page.locator("#qa-lab");
    await qaSection.scrollIntoViewIfNeeded();
    await expect(page.getByText("REQUIREMENT")).toBeVisible();
    await expect(page.getByText("TEST DESIGN")).toBeVisible();
    await expect(page.getByText("BUILD VERIFIED")).toBeVisible();
  });

  test("projects section shows project cards", async ({ page }) => {
    await page.goto("/");
    const projectsSection = page.locator("#projects");
    await projectsSection.scrollIntoViewIfNeeded();
    await expect(page.getByText("Project")).toBeVisible();
  });
});

test.describe("Branding", () => {
  test("Full Stack Developer is not present", async ({ page }) => {
    await page.goto("/");
    const content = await page.content();
    expect(content).not.toContain("Full Stack Developer");
    expect(content).not.toContain("Full-Stack Developer");
    expect(content).not.toContain("full-stack developer");
    expect(content).not.toContain("full stack developer");
  });

  test("QA Engineer is present", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByText("QA Engineer")).toBeVisible();
  });
});

test.describe("404", () => {
  test("shows 404 for non-existent page", async ({ page }) => {
    const response = await page.goto("/non-existent-page");
    expect(response?.status()).toBe(404);
  });
});

