import { test, expect } from "@playwright/test";

async function waitForBoot(page: import("@playwright/test").Page) {
  // Wait for boot sequence to complete and content to appear
  await page.waitForSelector("main.content-layer", { state: "attached" });
  // Wait for opacity transition to complete
  await page.waitForFunction(
    () => {
      const main = document.querySelector("main.content-layer");
      return main && getComputedStyle(main).opacity === "1";
    },
    { timeout: 10000 },
  );
}

test.describe("Page load", () => {
  test("homepage loads with correct title", async ({ page }) => {
    await page.goto("/");
    await expect(page).toHaveTitle(/Rohit Yadav/);
