  test("hero section is visible with name and title", async ({ page }) => {
    await page.goto("/");
    await waitForBoot(page);
    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
    await expect(page.getByText("ROHIT")).toBeVisible();
    await expect(page.getByText("YADAV")).toBeVisible();
    await expect(page.getByText("QA Engineer")).toBeVisible();
  });

  test("main landmark is present", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByRole("main")).toBeVisible();
  });
});

