@import "tailwindcss";

@theme {
  --color-void: var(--bg-void);
  --color-deep: var(--bg-deep);
  --color-surface: var(--bg-surface);
  --color-text: var(--fg-primary);
  --color-text-dim: var(--fg-secondary);
  --color-accent: var(--accent);
  --color-accent-glow: var(--accent-glow);
  --color-accent-subtle: var(--accent-subtle);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-error: #f87171;
  --color-success: #34d399;
  --font-geist: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

/* ===== DARK MODE (default) ===== */
:root {
  --bg-void: #05070a;
  --bg-deep: #0b1017;
  --bg-surface: #111923;
  --bg-elevated: #1a2332;
  --fg-primary: #f5f7fa;
  --fg-secondary: #8b95a5;
  --accent: #38bdf8;
  --accent-rgb: 56, 189, 248;
  --accent-glow: rgba(56, 189, 248, 0.15);
  --accent-subtle: rgba(56, 189, 248, 0.06);
  --border: rgba(255, 255, 255, 0.06);
  --border-strong: rgba(255, 255, 255, 0.12);
  --card-bg: rgba(5, 7, 10, 0.5);
  --card-border: rgba(56, 189, 248, 0.08);
  --glass-bg: rgba(10, 10, 18, 0.6);
  --section-glow: rgba(56, 189, 248, 0.04);
  --fog-color: #05070A;
  --theme-transition: 0.4s cubic-bezier(0.16, 1, 0.3, 1);
}

/* ===== LIGHT MODE ===== */
html.light {
  --bg-void: #f0f4f8;
  --bg-deep: #f7f9fc;
  --bg-surface: #ffffff;
  --bg-elevated: #eef3f8;
  --fg-primary: #0b1220;
  --fg-secondary: #526173;
  --accent: #0284c7;
  --accent-rgb: 2, 132, 199;
  --accent-glow: rgba(2, 132, 199, 0.12);
  --accent-subtle: rgba(2, 132, 199, 0.05);
  --border: rgba(0, 0, 0, 0.08);
  --border-strong: rgba(0, 0, 0, 0.14);
  --card-bg: rgba(255, 255, 255, 0.7);
  --card-border: rgba(2, 132, 199, 0.12);
  --glass-bg: rgba(255, 255, 255, 0.7);
  --section-glow: rgba(2, 132, 199, 0.04);
  --fog-color: #f0f4f8;
}

/* ===== GLOBAL RESET ===== */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  background: var(--bg-void);
  color: var(--fg-primary);
  font-family: var(--font-geist), system-ui, sans-serif;
  overflow-x: hidden;
  transition: background var(--theme-transition), color var(--theme-transition);
}

html,
body {
  min-height: 100%;
  cursor: none !important;
  overflow-x: hidden;
}

body {
  background: var(--bg-void);
  overflow-x: hidden;
  transition: background var(--theme-transition);
}

/* Prevent any section from causing horizontal overflow */
section {
  overflow-x: clip;
}

/* Hide default scrollbar */
::-webkit-scrollbar {
  width: 0;
  height: 0;
}
html {
  scrollbar-width: none;
}

/* Selection */
::selection {
  background: rgba(var(--accent-rgb), 0.3);
  color: var(--fg-primary);
}

/* ===== CANVAS ===== */
.canvas-container {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

/* ===== CONTENT LAYER ===== */
.content-layer {
  position: relative;
  z-index: 1;
  pointer-events: none;
}

.content-layer * {
  pointer-events: auto;
}

/* ===== CONTENT WRAPPER ===== */
.content-wrap {
  width: 100%;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

@media (min-width: 768px) {
  .content-wrap {
    padding-left: 2.5rem;
    padding-right: 2.5rem;
  }
}

@media (min-width: 1024px) {
  .content-wrap {
    padding-left: 3rem;
    padding-right: 3rem;
  }
}

/* ===== GLASS MORPHISM ===== */
.glass {
  background: var(--glass-bg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--border);
  transition: background var(--theme-transition), border-color var(--theme-transition);
}

/* ===== GRADIENT TEXT ===== */
.gradient-text {
  background: linear-gradient(135deg, var(--accent), #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ===== GLOW EFFECTS ===== */
.glow-accent {
  box-shadow:
    0 0 40px rgba(var(--accent-rgb), 0.1),
    0 0 80px rgba(var(--accent-rgb), 0.05);
}

.text-glow {
  text-shadow: 0 0 30px rgba(var(--accent-rgb), 0.3);
}

/* ===== MAGNETIC BUTTON ===== */
.magnetic-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  border: 1px solid rgba(var(--accent-rgb), 0.3);
  border-radius: 9999px;
  background: rgba(var(--accent-rgb), 0.05);
  color: var(--accent);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: none !important;
  transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}

.magnetic-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    circle at var(--mx, 50%) var(--my, 50%),
    rgba(var(--accent-rgb), 0.15),
    transparent 60%
  );
  opacity: 0;
  transition: opacity 0.4s;
}

.magnetic-btn:hover::before {
  opacity: 1;
}

.magnetic-btn:hover {
  border-color: rgba(var(--accent-rgb), 0.6);
  box-shadow: 0 0 30px rgba(var(--accent-rgb), 0.15);
}

/* ===== SYSTEM LABEL ===== */
.system-label {
  font-family: var(--font-mono), monospace;
  font-size: 0.625rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--fg-secondary);
}

/* ===== SCAN LINE ===== */
@keyframes scan {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}

.scan-line {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(var(--accent-rgb), 0.1), transparent);
  pointer-events: none;
  z-index: 100;
  animation: scan 8s linear infinite;
  opacity: 0.3;
}

html.light .scan-line {
  opacity: 0.15;
}

/* ===== BOOT SEQUENCE ===== */
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.cursor-blink {
  animation: blink 1s step-end infinite;
}

/* ===== FADE IN UP ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-fade-in-up {
  animation: fadeInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* ===== PARTICLE FADE ===== */
@keyframes particleFade {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}

/* ===== THEME TRANSITION ===== */
html.theme-transitioning,
html.theme-transitioning *,
html.theme-transitioning *::before,
html.theme-transitioning *::after {
  transition: background var(--theme-transition),
              color var(--theme-transition),
              border-color var(--theme-transition),
              box-shadow var(--theme-transition),
              opacity var(--theme-transition) !important;
}

/* ===== RESPONSIVE ===== */
@media (max-width: 768px) {
  html,
  body {
    cursor: auto !important;
  }

  .magnetic-btn {
    cursor: pointer !important;
  }
}

/* ===== REDUCED MOTION ===== */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }

  .scan-line {
    display: none;
  }
}

"use client";

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from "react";

type Theme = "dark" | "light";

interface ThemeContextValue {
  theme: Theme;
  toggle: () => void;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

export function useTheme() {
  return useContext(ThemeContext);
}

function getInitialTheme(): Theme {
  if (typeof window === "undefined") return "dark";
  const stored = localStorage.getItem("ryos-theme") as Theme | null;
  if (stored) return stored;
  return window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
}

function applyTheme(theme: Theme) {
  const root = document.documentElement;
  root.classList.add("theme-transitioning");
  root.classList.toggle("light", theme === "light");
  localStorage.setItem("ryos-theme", theme);
  // Remove transition class after animation completes
  setTimeout(() => root.classList.remove("theme-transitioning"), 500);
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>("dark");
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    const initial = getInitialTheme();
    setTheme(initial);
    document.documentElement.classList.toggle("light", initial === "light");
    setMounted(true);

    // Listen for system preference changes
    const mq = window.matchMedia("(prefers-color-scheme: light)");
    const handler = (e: MediaQueryListEvent) => {
      if (!localStorage.getItem("ryos-theme")) {
        const newTheme = e.matches ? "light" : "dark";
        setTheme(newTheme);
        applyTheme(newTheme);
      }
    };
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const toggle = useCallback(() => {
    setTheme((prev) => {
      const next = prev === "dark" ? "light" : "dark";
      applyTheme(next);
      return next;
    });
  }, []);

  // Prevent flash by not rendering children until theme is applied
  if (!mounted) {
    return <>{children}</>;
  }

  return <ThemeContext value={{ theme, toggle }}>{children}</ThemeContext>;
}

"use client";

import { motion } from "framer-motion";
import { useTheme } from "@/hooks/useTheme";
import { useCursor } from "@/hooks/useCursorContext";

export default function ThemeToggle() {
  const { theme, toggle } = useTheme();
  const { setCursor } = useCursor();
  const isDark = theme === "dark";

  return (
    <button
      onClick={toggle}
      className="relative w-9 h-9 flex items-center justify-center rounded-lg border border-[var(--border)] hover:border-[var(--accent)] bg-[var(--card-bg)] transition-all duration-300 cursor-none"
      onMouseEnter={() => setCursor("hover", isDark ? "LIGHT" : "DARK")}
      onMouseLeave={() => setCursor("default")}
      aria-label={`Switch to ${isDark ? "light" : "dark"} mode`}
    >
      <motion.div
        key={theme}
        initial={{ rotate: -90, scale: 0, opacity: 0 }}
        animate={{ rotate: 0, scale: 1, opacity: 1 }}
        exit={{ rotate: 90, scale: 0, opacity: 0 }}
        transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
      >
        {isDark ? (
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-[var(--accent)]">
            <circle cx="12" cy="12" r="4" />
            <path d="M12 2v2" />
            <path d="M12 20v2" />
            <path d="m4.93 4.93 1.41 1.41" />
            <path d="m17.66 17.66 1.41 1.41" />
            <path d="M2 12h2" />
            <path d="M20 12h2" />
            <path d="m6.34 17.66-1.41 1.41" />
            <path d="m19.07 4.93-1.41 1.41" />
          </svg>
        ) : (
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-[var(--accent)]">
            <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z" />
          </svg>
        )}
      </motion.div>
    </button>
  );
}

