  const [isComplete, setIsComplete] = useState(false);

  useEffect(() => {
    lines.forEach((line, index) => {
      setTimeout(() => {
        setVisibleLines(index + 1);
      }, line.delay);
    });

    setTimeout(() => {
      setIsComplete(true);
      setTimeout(onComplete, 500);
    }, 2400);
  }, [onComplete]);

  return (
    <AnimatePresence>
      {!isComplete && (
        <motion.div
          className="fixed inset-0 z-[10000] flex items-center justify-center"
          style={{ background: "var(--bg-primary)" }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.8, ease: "easeInOut" }}
        >
          <div className="max-w-md w-full px-8">
            <div className="border border-[rgba(var(--accent-rgb),0.15)] rounded-lg p-6 bg-[var(--card-bg)]">
              <div className="flex items-center gap-2 mb-6 pb-3 border-b border-[rgba(var(--accent-rgb),0.1)]">
                <div className="w-2 h-2 rounded-full bg-[#f87171]" />
                <div className="w-2 h-2 rounded-full bg-[#fbbf24]" />
                <div className="w-2 h-2 rounded-full bg-[#34d399]" />
                <span className="ml-2 font-mono text-[10px] tracking-[0.15em] text-[var(--fg-secondary)]">
                  RY/OS TERMINAL
                </span>
              </div>

              <div className="space-y-2">
                {lines.slice(0, visibleLines).map((line, index) => (
                  <motion.div
                    key={index}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ duration: 0.3 }}
                    className="flex items-center gap-2"
                  >
                    <span className="font-mono text-[10px] text-[var(--fg-secondary)]">{">"}</span>
                    <span
                      className="font-mono text-xs tracking-wider"
                      style={{
                        color: index === lines.length - 1 ? "var(--accent)" : "var(--fg-primary)",
                        textShadow:
                          index === lines.length - 1 ? "0 0 10px rgba(var(--accent-rgb), 0.5)" : "none",
                      }}
                    >
                      {line.text}
                    </span>
                  </motion.div>
                ))}
              </div>

              <div className="mt-4 flex items-center gap-2">
                <span className="font-mono text-[10px] text-[var(--fg-secondary)]">{">"}</span>
                <span className="w-2 h-4 bg-[var(--accent)] cursor-blink" />
              </div>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";

const sections = [
  { id: "hero", num: "01" },
  { id: "about", num: "02" },
  { id: "experience", num: "03" },
  { id: "skills", num: "04" },
  { id: "qa-lab", num: "05" },
  { id: "projects", num: "06" },
  { id: "contact", num: "07" },
];

export default function ScrollIndicator() {
  const [active, setActive] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const scrollPos = window.scrollY + window.innerHeight / 2;
      for (let i = sections.length - 1; i >= 0; i--) {
        const el = document.getElementById(sections[i].id);
        if (el && el.offsetTop <= scrollPos) {
          setActive(i);
          break;
        }
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollTo = (id: string) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <div className="fixed right-6 top-1/2 -translate-y-1/2 z-[90] hidden lg:flex flex-col items-center gap-3">
      <div className="relative w-[1px] h-32 bg-[rgba(var(--accent-rgb),0.1)]">
        <motion.div
          className="absolute top-0 left-0 w-full bg-[var(--accent)]"
          animate={{ height: `${((active + 1) / sections.length) * 100}%` }}
          transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        />
      </div>

      {sections.map((section, index) => (
        <button
          key={section.id}
          onClick={() => scrollTo(section.id)}
          className="relative flex items-center gap-2 cursor-none group"
        >
          <motion.span
            className="font-mono text-[9px] tracking-[0.15em]"
            animate={{
              color: index === active ? "var(--accent)" : "var(--fg-secondary)",
              textShadow: index === active ? "0 0 8px rgba(var(--accent-rgb), 0.5)" : "none",
            }}
            transition={{ duration: 0.3 }}
          >
            {section.num}
          </motion.span>
          <motion.div
            className="absolute -right-3 w-1.5 h-1.5 rounded-full"
            animate={{
              scale: index === active ? 1 : 0,
              backgroundColor: "var(--accent)",
            }}
            transition={{ duration: 0.3 }}
          />
        </button>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useMouse } from "@/hooks/useMouse";
import { useCursor } from "@/hooks/useCursorContext";

export default function CustomCursor() {
  const { smoothPosition, velocity, isMoving } = useMouse();
  const { variant, label } = useCursor();
  const dotRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);
  const labelRef = useRef<HTMLDivElement>(null);
  const [isTouchDevice, setIsTouchDevice] = useState(false);

  useEffect(() => {
    setIsTouchDevice(
      "ontouchstart" in window || navigator.maxTouchPoints > 0,
    );
  }, []);

  const sizeMap: Record<string, { dot: number; ring: number }> = {
    default: { dot: 6, ring: 32 },
    hover: { dot: 8, ring: 48 },
    expand: { dot: 10, ring: 64 },
    drag: { dot: 8, ring: 56 },
    text: { dot: 4, ring: 24 },
    explore: { dot: 10, ring: 64 },
  };

  const size = sizeMap[variant] || sizeMap.default;

  useEffect(() => {
    if (isTouchDevice || !dotRef.current || !ringRef.current) return;

    const dot = dotRef.current;
    const ring = ringRef.current;
    const lbl = labelRef.current;

    dot.style.transform = `translate(${smoothPosition.x - size.dot / 2}px, ${smoothPosition.y - size.dot / 2}px)`;
    ring.style.transform = `translate(${smoothPosition.x - size.ring / 2}px, ${smoothPosition.y - size.ring / 2}px) scale(${isMoving ? 1 + Math.min(velocity * 0.005, 0.3) : 1})`;

    if (lbl) {
      lbl.style.transform = `translate(${smoothPosition.x}px, ${smoothPosition.y + 24}px)`;
    }
  }, [smoothPosition, velocity, isMoving, size, isTouchDevice]);

  if (isTouchDevice) return null;

  return (
    <>
      <div
        ref={dotRef}
        className="fixed top-0 left-0 pointer-events-none z-[9999] mix-blend-difference"
        style={{
          width: size.dot,
          height: size.dot,
          borderRadius: "50%",
          background: variant === "default" ? "var(--accent)" : "#fff",
          transition: "width 0.3s, height 0.3s, background 0.3s",
          willChange: "transform",
        }}
      />

      <div
        ref={ringRef}
        className="fixed top-0 left-0 pointer-events-none z-[9998]"
        style={{
          width: size.ring,
          height: size.ring,
          borderRadius: "50%",
          border: `1px solid ${variant === "default" ? "rgba(var(--accent-rgb), 0.3)" : "rgba(255, 255, 255, 0.4)"}`,
          transition:
            "width 0.4s cubic-bezier(0.16, 1, 0.3, 1), height 0.4s cubic-bezier(0.16, 1, 0.3, 1), border 0.3s",
          willChange: "transform",
        }}
      />

      {label && (
        <div
          ref={labelRef}
          className="fixed top-0 left-0 pointer-events-none z-[9999] mix-blend-difference"
          style={{
            transform: `translate(${smoothPosition.x}px, ${smoothPosition.y + 24}px)`,
            transition: "opacity 0.2s",
            willChange: "transform",
          }}
        >
          <span
            className="font-mono text-[10px] tracking-[0.2em] uppercase whitespace-nowrap"
            style={{
              color: "var(--fg-primary)",
              textShadow: "0 0 10px rgba(var(--accent-rgb), 0.5)",
            }}
          >
            {label}
          </span>
        </div>
      )}
    </>
  );
}

