import { test, expect } from "@playwright/test";

const pages = ["/about", "/experience", "/skills", "/qa-lab", "/projects", "/contact"];

for (const path of pages) {
  test(`scroll works on ${path}`, async ({ page }) => {
    await page.goto(path);
    await page.waitForTimeout(1000);

    const scrollHeight = await page.evaluate(() => document.body.scrollHeight);
    const viewportHeight = await page.evaluate(() => window.innerHeight);
    const scrollYBefore = await page.evaluate(() => window.scrollY);

    console.log(`${path}: scrollHeight=${scrollHeight}, viewportHeight=${viewportHeight}, scrollY=${scrollYBefore}`);

    // Try scrolling
    await page.evaluate(() => window.scrollBy(0, 500));
    const scrollYAfter = await page.evaluate(() => window.scrollY);

    console.log(`${path}: after scroll scrollY=${scrollYAfter}`);

    // Check if page has overflow (content taller than viewport)
    const hasOverflow = scrollHeight > viewportHeight;
    console.log(`${path}: hasOverflow=${hasOverflow}`);

    // Get computed overflow on html and body
    const htmlOverflow = await page.evaluate(() => {
      const html = document.documentElement;
      const body = document.body;
      const htmlStyle = window.getComputedStyle(html);
      const bodyStyle = window.getComputedStyle(body);
      return {
        htmlOverflowX: htmlStyle.overflowX,
        htmlOverflowY: htmlStyle.overflowY,
        bodyOverflowX: bodyStyle.overflowX,
        bodyOverflowY: bodyStyle.overflowY,
        htmlHeight: htmlStyle.height,
        bodyHeight: bodyStyle.height,
        htmlMinHeight: htmlStyle.minHeight,
        bodyMinHeight: bodyStyle.minHeight,
      };
    });
    console.log(`${path}: html/body styles:`, JSON.stringify(htmlOverflow));

    // Check content-layer
    const contentLayerInfo = await page.evaluate(() => {
      const cl = document.querySelector(".content-layer");
      if (!cl) return { exists: false };
      const rect = cl.getBoundingClientRect();
      const style = window.getComputedStyle(cl);
      return {
        exists: true,
        height: rect.height,
        top: rect.top,
        position: style.position,
        overflow: style.overflow,
        overflowY: style.overflowY,
        pointerEvents: style.pointerEvents,
      };
    });
    console.log(`${path}: content-layer:`, JSON.stringify(contentLayerInfo));

    // Check all sections for overflow
    const sectionsInfo = await page.evaluate(() => {
      const sections = document.querySelectorAll("section");
      return Array.from(sections).map((s, i) => {
        const style = window.getComputedStyle(s);
        const rect = s.getBoundingClientRect();
        return {
          index: i,
          overflowX: style.overflowX,
          overflowY: style.overflowY,
          height: rect.height,
          top: rect.top,
          className: s.className.substring(0, 80),
        };
      });
    });
    console.log(`${path}: sections:`, JSON.stringify(sectionsInfo));
  });
}

