"use client";

import { useRef, useMemo, useState } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

const PIPELINE_STAGES = [
  { label: "REQUIREMENT", color: "#8b95a5" },
  { label: "TEST DESIGN", color: "#818CF8" },
  { label: "EXECUTION", color: "#38BDF8" },
  { label: "BUG DETECT", color: "#f87171" },
  { label: "DEFECT TRACK", color: "#fbbf24" },
  { label: "FIX", color: "#34D399" },
  { label: "RETEST", color: "#38BDF8" },
  { label: "REGRESSION", color: "#818CF8" },
  { label: "RELEASE", color: "#34D399" },
];

const NODE_COUNT = PIPELINE_STAGES.length;
const PIPELINE_HEIGHT = 5.5;
const PIPELINE_X = 2.8;
const SPACING = PIPELINE_HEIGHT / (NODE_COUNT - 1);

function generateFlowParticles(count: number) {
  return Array.from({ length: count }, (_, i) => ({
    segment: i % (NODE_COUNT - 1),
    offset: Math.random(),
    speed: 0.15 + Math.random() * 0.2,
    scale: 0.02 + Math.random() * 0.015,
  }));
}

interface QAPipelineProps {
  isDark: boolean;
  mousePosition: { x: number; y: number };
}

export default function QAPipeline({ isDark, mousePosition }: QAPipelineProps) {
  const groupRef = useRef<THREE.Group>(null);
  const nodesRef = useRef<THREE.InstancedMesh>(null);
  const connectionsRef = useRef<THREE.Group>(null);
  const flowRef = useRef<THREE.InstancedMesh>(null);
  const glowRef = useRef<THREE.InstancedMesh>(null);
  const dummy = useState(() => new THREE.Object3D())[0];
  const [flowParticles] = useState(() => generateFlowParticles(24));

  const accentColor = isDark ? "#38BDF8" : "#0284c7";
  const nodeOpacity = isDark ? 0.7 : 0.4;
  const flowOpacity = isDark ? 0.8 : 0.4;
  const glowOpacity = isDark ? 0.15 : 0.08;

  const nodePositions = useMemo(() => {
    return PIPELINE_STAGES.map((_, i) => {
      const y = PIPELINE_HEIGHT / 2 - i * SPACING;
      const wobble = Math.sin(i * 1.7) * 0.15;
      return new THREE.Vector3(PIPELINE_X + wobble, y, 0);
    });
  }, []);

  const lineGeometries = useMemo(() => {
    return nodePositions.slice(0, -1).map((pos, i) => {
      const next = nodePositions[i + 1];
      const points = [pos, next];
      const geo = new THREE.BufferGeometry().setFromPoints(points);
      return geo;
    });
  }, [nodePositions]);

  const lineMaterials = useMemo(() => {
    return nodePositions.slice(0, -1).map((_, i) => {
      return new THREE.LineBasicMaterial({
        color: accentColor,
        transparent: true,
        opacity: isDark ? 0.12 : 0.06,
      });
    });
  }, [accentColor, isDark]);

  const nodeMat = useMemo(
    () =>
      new THREE.MeshBasicMaterial({
        color: accentColor,
        transparent: true,
        opacity: nodeOpacity,
      }),
    [accentColor, nodeOpacity],
  );

  const glowMat = useMemo(
    () =>
      new THREE.MeshBasicMaterial({
        color: accentColor,
        transparent: true,
        opacity: glowOpacity,
      }),
    [accentColor, glowOpacity],
  );

  useFrame((state) => {
    const time = state.clock.elapsedTime;

    if (groupRef.current) {
      const targetRotY = mousePosition.x * 0.08;
      const targetRotX = mousePosition.y * 0.05;
      groupRef.current.rotation.y +=
        (targetRotY - groupRef.current.rotation.y) * 0.04;
      groupRef.current.rotation.x +=
        (targetRotX - groupRef.current.rotation.x) * 0.04;
    }

    if (nodesRef.current) {
      nodePositions.forEach((pos, i) => {
        const float = Math.sin(time * 0.5 + i * 0.8) * 0.04;
        dummy.position.set(pos.x, pos.y + float, pos.z);
        const pulse = 1 + Math.sin(time * 1.5 + i * 0.6) * 0.15;
        dummy.scale.setScalar(pulse);
        dummy.updateMatrix();
        nodesRef.current!.setMatrixAt(i, dummy.matrix);
      });
      nodesRef.current.instanceMatrix.needsUpdate = true;
    }

    if (glowRef.current) {
      nodePositions.forEach((pos, i) => {
        const float = Math.sin(time * 0.5 + i * 0.8) * 0.04;
        dummy.position.set(pos.x, pos.y + float, pos.z);
        const glowPulse = 1.8 + Math.sin(time * 1.2 + i * 0.5) * 0.4;
        dummy.scale.setScalar(glowPulse);
        dummy.updateMatrix();
        glowRef.current!.setMatrixAt(i, dummy.matrix);
      });
      glowRef.current.instanceMatrix.needsUpdate = true;
    }

    if (flowRef.current) {
      flowParticles.forEach((p, i) => {
        p.offset = (p.offset + p.speed * 0.01) % 1;
        const from = nodePositions[p.segment];
        const to = nodePositions[p.segment + 1];
        if (!from || !to) return;
        const t = p.offset;
        const x = from.x + (to.x - from.x) * t;
        const y = from.y + (to.y - from.y) * t;
        const z = from.z + (to.z - from.z) * t;
        const wobble = Math.sin(time * 3 + i) * 0.03;
        dummy.position.set(x + wobble, y, z);
        const fadeIn = t < 0.1 ? t / 0.1 : t > 0.9 ? (1 - t) / 0.1 : 1;
        dummy.scale.setScalar(p.scale * (0.5 + fadeIn * 0.5));
        dummy.updateMatrix();
        flowRef.current!.setMatrixAt(i, dummy.matrix);
      });
      flowRef.current.instanceMatrix.needsUpdate = true;
    }

    if (connectionsRef.current) {
      connectionsRef.current.children.forEach((child, i) => {
        if (child instanceof THREE.Line && child.material instanceof THREE.LineBasicMaterial) {
          const baseOpacity = isDark ? 0.12 : 0.06;
          child.material.opacity =
            baseOpacity + Math.sin(time * 0.8 + i * 0.5) * 0.04;
        }
      });
    }
  });

  return (
    <group ref={groupRef}>
      {lineGeometries.map((geo, i) => (
        <line key={`conn-${i}`} geometry={geo} material={lineMaterials[i]} />
      ))}

      <group ref={connectionsRef} />

      <instancedMesh ref={glowRef} args={[undefined, undefined, NODE_COUNT]}>
        <sphereGeometry args={[1, 8, 8]} />
        <primitive object={glowMat} attach="material" />
      </instancedMesh>

      <instancedMesh ref={nodesRef} args={[undefined, undefined, NODE_COUNT]}>
        <sphereGeometry args={[0.08, 8, 8]} />
        <primitive object={nodeMat} attach="material" />
      </instancedMesh>

      <instancedMesh ref={flowRef} args={[undefined, undefined, 24]}>
        <sphereGeometry args={[1, 4, 4]} />
        <meshBasicMaterial color={accentColor} transparent opacity={flowOpacity} />
      </instancedMesh>

      {nodePositions.map((pos, i) => {
        const stage = PIPELINE_STAGES[i];
        return (
          <group key={stage.label} position={[pos.x + 0.25, pos.y, pos.z]}>
            <mesh position={[-0.15, 0, 0]}>
              <planeGeometry args={[0.04, 0.04]} />
              <meshBasicMaterial
                color={stage.color}
                transparent
                opacity={isDark ? 0.9 : 0.6}
              />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

"use client";

import { Canvas } from "@react-three/fiber";
import { Preload } from "@react-three/drei";
import { Suspense, useState, useEffect, createContext, useContext, useRef } from "react";
import Environment from "./Environment";
import Particles from "./Particles";
import NeuralCore from "./NeuralCore";
import QAPipeline from "./QAPipeline";
import { useTheme } from "@/hooks/useTheme";

interface MouseContextType {
  x: number;
  y: number;
}

const MouseContext = createContext<MouseContextType>({ x: 0, y: 0 });

export function useSceneMouse() {
  return useContext(MouseContext);
}

function useIsMobile() {
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);
  return isMobile;
}

function MouseTracker({ children }: { children: React.ReactNode }) {
  const ref = useRef({ x: 0, y: 0 });
  const [pos, setPos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      ref.current.x = (e.clientX / window.innerWidth) * 2 - 1;
      ref.current.y = -(e.clientY / window.innerHeight) * 2 + 1;
    };
    let raf: number;
    const tick = () => {
      setPos((prev) => ({
        x: prev.x + (ref.current.x - prev.x) * 0.05,
        y: prev.y + (ref.current.y - prev.y) * 0.05,
      }));
      raf = requestAnimationFrame(tick);
    };
    window.addEventListener("mousemove", handleMove, { passive: true });
    raf = requestAnimationFrame(tick);
    return () => {
      window.removeEventListener("mousemove", handleMove);
      cancelAnimationFrame(raf);
    };
  }, []);

  return <MouseContext.Provider value={pos}>{children}</MouseContext.Provider>;
}

export default function Scene() {
  const isMobile = useIsMobile();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const fogColor = isDark ? "#05070A" : "#f0f4f8";
  const ambientIntensity = isDark ? 0.15 : 0.4;
  const pointIntensity = isDark ? 0.4 : 0.25;
  const dirIntensity = isDark ? 0.3 : 0.5;

  return (
    <div className="canvas-container">
      <MouseTracker>
        <Canvas
          camera={{ position: [0, 0, 5], fov: 60, near: 0.1, far: 100 }}
          dpr={isMobile ? [1, 1] : [1, 1.5]}
          gl={{
            antialias: !isMobile,
            alpha: true,
            powerPreference: "high-performance",
          }}
          style={{ background: "transparent" }}
        >
          <Suspense fallback={null}>
            <fog attach="fog" args={[fogColor, 3, 15]} />
            <ambientLight intensity={ambientIntensity} />
            <pointLight
              position={[5, 5, 5]}
              intensity={pointIntensity}
              color={isDark ? "#38BDF8" : "#0284c7"}
            />
            <pointLight position={[-5, -3, 3]} intensity={isDark ? 0.2 : 0.15} color="#818CF8" />
