"use client";

import { useRef, useMemo, useState } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

const PIPELINE_STAGES = [
  { label: "REQUIREMENT", color: "#8b95a5" },
  { label: "TEST DESIGN", color: "#818CF8" },
  { label: "EXECUTION", color: "#38BDF8" },
  { label: "BUG DETECT", color: "#f87171" },
  { label: "DEFECT TRACK", color: "#fbbf24" },
  { label: "FIX", color: "#34D399" },
  { label: "RETEST", color: "#38BDF8" },
  { label: "REGRESSION", color: "#818CF8" },
  { label: "RELEASE", color: "#34D399" },
];

const NODE_COUNT = PIPELINE_STAGES.length;
const PIPELINE_HEIGHT = 5.5;
const PIPELINE_X = 2.8;
const SPACING = PIPELINE_HEIGHT / (NODE_COUNT - 1);

function generateFlowParticles(count: number) {
  return Array.from({ length: count }, () => ({
    segment: 0,
    offset: Math.random(),
    speed: 0.15 + Math.random() * 0.2,
    scale: 0.02 + Math.random() * 0.015,
  }));
}

interface QAPipelineProps {
  isDark: boolean;
  mousePosition: { x: number; y: number };
}

function ConnectionLine({
  from,
  to,
  color,
  opacity,
}: {
  from: THREE.Vector3;
  to: THREE.Vector3;
  color: string;
  opacity: number;
}) {
  const ref = useRef<THREE.Mesh>(null);

  const { position, rotation, length } = useMemo(() => {
    const mid = new THREE.Vector3().addVectors(from, to).multiplyScalar(0.5);
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    const angle = Math.atan2(dir.y, dir.x);
    return { position: mid, rotation: angle, length: len };
  }, [from, to]);

  return (
    <mesh ref={ref} position={[position.x, position.y, position.z]} rotation={[0, 0, rotation]}>
      <planeGeometry args={[length, 0.008]} />
      <meshBasicMaterial color={color} transparent opacity={opacity} />
    </mesh>
  );
}

export default function QAPipeline({ isDark, mousePosition }: QAPipelineProps) {
  const groupRef = useRef<THREE.Group>(null);
  const nodesRef = useRef<THREE.InstancedMesh>(null);
  const flowRef = useRef<THREE.InstancedMesh>(null);
  const glowRef = useRef<THREE.InstancedMesh>(null);
  const dummy = useState(() => new THREE.Object3D())[0];
  const [flowParticles] = useState(() => generateFlowParticles(24));

  const accentColor = isDark ? "#38BDF8" : "#0284c7";
  const nodeOpacity = isDark ? 0.7 : 0.4;
  const flowOpacity = isDark ? 0.8 : 0.4;
  const glowOpacity = isDark ? 0.15 : 0.08;

  const nodePositions = useMemo(() => {
    return PIPELINE_STAGES.map((_, i) => {
      const y = PIPELINE_HEIGHT / 2 - i * SPACING;
      const wobble = Math.sin(i * 1.7) * 0.15;
      return new THREE.Vector3(PIPELINE_X + wobble, y, 0);
    });
  }, []);

  const connections = useMemo(() => {
    return nodePositions.slice(0, -1).map((pos, i) => ({
      from: pos,
      to: nodePositions[i + 1],
      color: accentColor,
      opacity: isDark ? 0.12 : 0.06,
    }));
  }, [nodePositions, accentColor, isDark]);

  const nodeMat = useMemo(
    () =>
      new THREE.MeshBasicMaterial({
        color: accentColor,
        transparent: true,
        opacity: nodeOpacity,
      }),
    [accentColor, nodeOpacity],
  );

  const glowMat = useMemo(
    () =>
      new THREE.MeshBasicMaterial({
        color: accentColor,
        transparent: true,
        opacity: glowOpacity,
      }),
    [accentColor, glowOpacity],
  );

  useFrame((state) => {
    const time = state.clock.elapsedTime;

    if (groupRef.current) {
      const targetRotY = mousePosition.x * 0.08;
      const targetRotX = mousePosition.y * 0.05;
      groupRef.current.rotation.y += (targetRotY - groupRef.current.rotation.y) * 0.04;
      groupRef.current.rotation.x += (targetRotX - groupRef.current.rotation.x) * 0.04;
    }

    if (nodesRef.current) {
      nodePositions.forEach((pos, i) => {
        const float = Math.sin(time * 0.5 + i * 0.8) * 0.04;
        dummy.position.set(pos.x, pos.y + float, pos.z);
        const pulse = 1 + Math.sin(time * 1.5 + i * 0.6) * 0.15;
        dummy.scale.setScalar(pulse);
        dummy.updateMatrix();
        nodesRef.current!.setMatrixAt(i, dummy.matrix);
      });
      nodesRef.current.instanceMatrix.needsUpdate = true;
    }

    if (glowRef.current) {
      nodePositions.forEach((pos, i) => {
        const float = Math.sin(time * 0.5 + i * 0.8) * 0.04;
        dummy.position.set(pos.x, pos.y + float, pos.z);
        const glowPulse = 1.8 + Math.sin(time * 1.2 + i * 0.5) * 0.4;
        dummy.scale.setScalar(glowPulse);
        dummy.updateMatrix();
        glowRef.current!.setMatrixAt(i, dummy.matrix);
      });
      glowRef.current.instanceMatrix.needsUpdate = true;
    }

    if (flowRef.current) {
      flowParticles.forEach((p, i) => {
        p.offset = (p.offset + p.speed * 0.01) % 1;
        const seg = i % (NODE_COUNT - 1);
        const from = nodePositions[seg];
        const to = nodePositions[seg + 1];
        if (!from || !to) return;
        const t = p.offset;
        const x = from.x + (to.x - from.x) * t;
        const y = from.y + (to.y - from.y) * t;
        const z = from.z + (to.z - from.z) * t;
        const wobble = Math.sin(time * 3 + i) * 0.03;
        dummy.position.set(x + wobble, y, z);
        const fadeIn = t < 0.1 ? t / 0.1 : t > 0.9 ? (1 - t) / 0.1 : 1;
        dummy.scale.setScalar(p.scale * (0.5 + fadeIn * 0.5));
        dummy.updateMatrix();
        flowRef.current!.setMatrixAt(i, dummy.matrix);
      });
      flowRef.current.instanceMatrix.needsUpdate = true;
    }
  });

  return (
    <group ref={groupRef}>
      {connections.map((conn, i) => (
        <ConnectionLine
          key={`conn-${i}`}
          from={conn.from}
          to={conn.to}
          color={conn.color}
          opacity={conn.opacity}
        />
      ))}

      <instancedMesh ref={glowRef} args={[undefined, undefined, NODE_COUNT]}>
        <sphereGeometry args={[1, 8, 8]} />
        <primitive object={glowMat} attach="material" />
      </instancedMesh>

      <instancedMesh ref={nodesRef} args={[undefined, undefined, NODE_COUNT]}>
        <sphereGeometry args={[0.08, 8, 8]} />
        <primitive object={nodeMat} attach="material" />
      </instancedMesh>

      <instancedMesh ref={flowRef} args={[undefined, undefined, 24]}>
        <sphereGeometry args={[1, 4, 4]} />
        <meshBasicMaterial color={accentColor} transparent opacity={flowOpacity} />
      </instancedMesh>

      {nodePositions.map((pos, i) => {
        const stage = PIPELINE_STAGES[i];
        return (
          <group key={stage.label} position={[pos.x + 0.25, pos.y, pos.z]}>
            <mesh position={[-0.15, 0, 0]}>
              <planeGeometry args={[0.04, 0.04]} />
              <meshBasicMaterial color={stage.color} transparent opacity={isDark ? 0.9 : 0.6} />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

"use client";

import { useRef, useMemo, useState } from "react";
import { useFrame } from "@react-three/fiber";
import { Float, MeshDistortMaterial } from "@react-three/drei";
import * as THREE from "three";

function CoreSphere() {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (!ref.current) return;
    const t = state.clock.getElapsedTime();
    ref.current.rotation.y = t * 0.15;
    ref.current.rotation.x = Math.sin(t * 0.1) * 0.1;
  });

  return (
    <Float speed={1.5} rotationIntensity={0.3} floatIntensity={0.5}>
      <mesh ref={ref} scale={1.1}>
        <icosahedronGeometry args={[1, 4]} />
        <MeshDistortMaterial
          color="#38BDF8"
          emissive="#38BDF8"
          emissiveIntensity={0.15}
          roughness={0.3}
          metalness={0.8}
          distort={0.15}
          speed={1.5}
          wireframe
        />
      </mesh>
    </Float>
  );
}

function OrbitalRing({
  radius,
  speed,
  tilt,
  color,
}: {
  radius: number;
  speed: number;
  tilt: number;
  color: string;
}) {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (!ref.current) return;
    ref.current.rotation.z = tilt;
    ref.current.rotation.y = state.clock.getElapsedTime() * speed;
  });

  return (
    <mesh ref={ref}>
      <torusGeometry args={[radius, 0.008, 8, 100]} />
      <meshStandardMaterial
        color={color}
        emissive={color}
        emissiveIntensity={0.5}
        transparent
        opacity={0.4}
      />
    </mesh>
  );
}

function FloatingNode({
  position,
  color,
  speed,
}: {
  position: [number, number, number];
  color: string;
  speed: number;
}) {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (!ref.current) return;
    const t = state.clock.getElapsedTime() * speed;
    ref.current.position.x = position[0] + Math.sin(t) * 0.15;
    ref.current.position.y = position[1] + Math.cos(t * 0.8) * 0.15;
    ref.current.position.z = position[2] + Math.sin(t * 0.6) * 0.1;
  });

  return (
    <mesh ref={ref} position={position} scale={0.06}>
      <sphereGeometry args={[1, 12, 12]} />
      <meshStandardMaterial
        color={color}
        emissive={color}
        emissiveIntensity={0.8}
        transparent
        opacity={0.9}
      />
    </mesh>
  );
}

function ParticleField() {
  const count = 40;
  const [positions] = useState(() => {
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 5;
      pos[i * 3 + 1] = (Math.random() - 0.5) * 5;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 5;
    }
    return pos;
  });

  const ref = useRef<THREE.Points>(null);

  useFrame((state) => {
    if (!ref.current) return;
    ref.current.rotation.y = state.clock.getElapsedTime() * 0.02;
  });

  const geometry = useMemo(() => {
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    return geo;
  }, [positions]);

  return (
    <points ref={ref} geometry={geometry}>
      <pointsMaterial color="#38BDF8" size={0.02} transparent opacity={0.6} sizeAttenuation />
    </points>
  );
}

export default function Globe({ className = "" }: { className?: string }) {
  return (
    <group className={className}>
      <CoreSphere />
      <OrbitalRing radius={1.6} speed={0.2} tilt={Math.PI * 0.3} color="#38BDF8" />
      <OrbitalRing radius={1.9} speed={-0.15} tilt={Math.PI * 0.6} color="#818CF8" />
      <OrbitalRing radius={2.2} speed={0.1} tilt={Math.PI * 0.1} color="#6366f1" />
      <FloatingNode position={[1.5, 0.8, 0.5]} color="#38BDF8" speed={1.2} />
      <FloatingNode position={[-1.2, -0.6, 0.8]} color="#818CF8" speed={0.9} />
      <FloatingNode position={[0.5, -1.3, -0.5]} color="#6366f1" speed={1.1} />
      <FloatingNode position={[-0.8, 1.1, -0.3]} color="#34d399" speed={0.8} />
      <ParticleField />
    </group>
  );
}

